/* WF-W03-03-01/02: memory-only document review; never a submission or admission. */
const ADMISSIONS={started:false,reviewed:false,quality:{},request:null,reason:'',error:'',events:[]};
const reviewLabels={pending:['Prüfung offen','Review pending'],accepted:['Im Muster geprüft','Reviewed in sample'],unreadable:['Unlesbar / abgeschnitten','Unreadable / cropped'],unclear:['Dokumenttyp ungeklärt','Document type unclear']};
function reviewIssues(){return [0,1,2].filter(i=>!state.uploads[i]||ADMISSIONS.quality[i]!=='accepted')}
function reviewPending(){return [0,1,2].some(i=>state.uploads[i]&&(!ADMISSIONS.quality[i]||ADMISSIONS.quality[i]==='pending'))}
function reviewState(){if(!ADMISSIONS.started)return t('Entwurf · noch nicht zur lokalen Prüfung übernommen','Draft · not yet opened for local review');if(ADMISSIONS.request){if(ADMISSIONS.request.responded&&!ADMISSIONS.reviewed)return t('Nachreichung · erneute Prüfung offen','Additional evidence · review pending');return t('Unterlagen unvollständig · Nachforderung vorbereitet','Documents incomplete · request prepared')}if(!ADMISSIONS.reviewed)return t('Vollständigkeitsprüfung offen','Completeness review pending');return reviewIssues().length?t('Unterlagen ungeklärt oder unvollständig','Documents unclear or incomplete'):t('Vollständigkeit im Muster geprüft · Fachprüfung offen','Sample completeness reviewed · eligibility review pending')}
function reviewLog(){return `<ol class="review-log">${ADMISSIONS.events.map((e,i)=>`<li><b>${i+1}.</b> ${esc(t(...e))}</li>`).join('')||`<li>${t('Noch keine lokalen Prüfschritte.','No local review steps yet.')}</li>`}</ol>`}
function reviewNotice(){return `<p class="review-notice">${t('Lokale Simulation · nur fiktive Angaben. Keine Übermittlung, keine echten Dateien, keine Anmeldung. Beim Neuladen wird dieser Stand verworfen.','Local simulation · fictional details only. No transmission, real files or enrolment. This state is discarded on reload.')}</p>`}
function reviewButton(de,en,act,disabled=false){return `<button type="button" class="btn secondary" data-review-action="${act}" ${disabled?'disabled':''}>${t(de,en)}</button>`}
function reviewDocumentRows(staff=false){return [0,1,2].map(i=>`<div class="review-document"><div><h3>${esc(docNames()[i])}</h3><p>${state.uploads[i]?t(...reviewLabels[ADMISSIONS.quality[i]||'pending']):t('Muster fehlt','Sample missing')}</p></div>${staff&&state.uploads[i]?`<label class="field">${t('Musterprüfung','Sample review')} · ${esc(docNames()[i])}<select data-review-quality="${i}">${Object.entries(reviewLabels).map(([k,v])=>`<option value="${k}" ${(ADMISSIONS.quality[i]||'pending')===k?'selected':''}>${t(...v)}</option>`).join('')}</select></label>`:!staff?reviewButton(state.uploads[i]?'Muster ersetzen':'Muster ergänzen',state.uploads[i]?'Replace sample':'Add sample','document-'+i):''}</div>`).join('')}
function reviewApplicant(){const a=ADMISSIONS,r=a.request;return `<section class="review-panel" aria-labelledby="review-status"><span class="eyebrow">DEMO-001 · ${t('LOKALER PRÜFWEG','LOCAL REVIEW JOURNEY')}</span><h2 id="review-status" tabindex="-1">${t('Prüfung & Rückmeldung','Review & response')}</h2>${reviewNotice()}<p class="review-status">${reviewState()}</p>${r?`<h3>${t('Vorbereitete Nachforderung · nicht versendet','Prepared document request · not sent')}</h3><p>${esc(r.reason)}</p><ul>${r.items.map(i=>`<li>${esc(docNames()[i])} — ${t(...r.labels[i])}</li>`).join('')}</ul><p>${t('Bitte vollständige, lesbare Seiten ergänzen. Unklare Dokumente werden persönlich zugeordnet.','Please provide complete, legible pages. Unclear documents require personal classification.')}</p>${reviewDocumentRows()}${reviewButton('Nachreichung zur lokalen Prüfung vormerken','Mark additional evidence for local review','respond',r.responded)}<p>${t('Eine Nachreichung bestätigt noch keine Vollständigkeit.','Additional evidence does not confirm completeness.')}</p>`:!a.started?reviewButton('Entwurf in lokale Prüfung übernehmen','Open draft for local review','start'):`<p>${t('Persönlicher Erstkontakt und fachliche Prüfung bleiben offen.','Personal first contact and eligibility review remain pending.')}</p>`}<details><summary>${t('Lokaler Verlauf','Local history')}</summary>${reviewLog()}</details><div class="actions">${link(t('Mitarbeiteransicht · Demo','Staff view · demo'),'/staff/admissions/DEMO-001','secondary')}</div></section>`}
function reviewStaff(r){const a=ADMISSIONS;const intro=`<section class="v3-page-intro"><span class="eyebrow">${t('ZULASSUNGSBÜRO · LOKALE DEMO','ADMISSIONS OFFICE · LOCAL DEMO')}</span><h1>${t('Bewerbungsprüfung','Application review')}</h1>${reviewNotice()}<nav class="actions" aria-label="${t('Prüfweg','Review journey')}">${link(t('Arbeitsliste','Work queue'),'/staff/admissions','secondary')}${link(t('Bewerberansicht','Applicant view'),'/portal/applicant','secondary')}</nav></section>`;
if(r==='/staff/admissions')return intro+`<section class="review-panel"><h2>${t('Lokale Bewerberakte','Local applicant record')}</h2>${a.started?`<div class="review-document"><div><h3>DEMO-001</h3><p>${esc(state.application.course)} · ${reviewState()}</p></div>${link(t('Akte prüfen','Review record'),'/staff/admissions/DEMO-001')}</div>`:`<p>${t('Keine Akte zur lokalen Prüfung übernommen. Bereite zuerst den Bewerbungsentwurf vor.','No record opened for local review. Prepare the application draft first.')}</p>${link(t('Zum Entwurf','Open draft'),'/apply','secondary')}`}</section>`;
if(r!=='/staff/admissions/DEMO-001')return intro+`<section class="review-panel"><h2>${t('Musterakte nicht gefunden','Sample record not found')}</h2><p>${t('Es wird keine Akte aus einer unbekannten Kennung erzeugt.','Unknown identifiers do not create records.')}</p></section>`;
return intro+`<section class="review-panel"><h2 id="review-title" tabindex="-1">DEMO-001 · ${t('Unterlagen prüfen','Review documents')}</h2><p class="review-status">${reviewState()}</p>${!a.started?`<p>${t('Der Bewerberentwurf wurde noch nicht in den lokalen Prüfweg übernommen.','The applicant draft has not yet entered the local review journey.')}</p>${link(t('Zum Bewerberentwurf','Open applicant draft'),'/portal/applicant','secondary')}`:`<div class="review-columns"><div><h3>${t('Bildungsziel & Unterlagen','Study goal & documents')}</h3><p>${esc(state.application.course)} · ${esc(applicationChoiceLabel(state.application.language))}</p>${applicationDraftDetails()}${reviewDocumentRows(true)}${reviewButton('Vollständigkeitsprüfung vormerken','Record completeness review','review')}<p>${t('Die drei Musterunterlagen sind keine freigegebene angebotsbezogene Pflichtliste. OCR, Dublettenabgleich und Echtheitsprüfung sind nicht angebunden.','The three sample documents are not an approved programme-specific requirement list. OCR, duplicate detection and authenticity checks are not connected.')}</p></div><div><h3>${t('Nachforderung vorbereiten','Prepare document request')}</h3><p>${t('Nur aktuelle Lücken nach abgeschlossener Musterprüfung. Kein Versand und kein Fristbeginn.','Current gaps only, after sample review. No sending and no deadline starts.')}</p><label class="field">${t('Begründung für Bewerber · nur fiktiv','Reason for applicant · fictional only')}<textarea id="review-reason" maxlength="1200">${esc(a.reason)}</textarea></label><p id="review-error" role="alert" tabindex="-1">${esc(a.error)}</p>${reviewButton('Nachforderung lokal vorbereiten','Prepare request locally','request',!a.reviewed||!reviewIssues().length)}<h3>${t('Persönlicher Erstkontakt','Personal first contact')}</h3><p>${t('Offene Aufgabe für das Zulassungsbüro – auch bei vollständigen Unterlagen. Kein Kontakt wurde durchgeführt.','Open task for the admissions office, including complete records. No contact has taken place.')}</p><details><summary>${t('Quellengebundene Folgeschritte','Source-defined next steps')}</summary><p>${t('Erst nach tatsächlicher Nachforderung: nach 3 Kalendertagen ohne Reaktion Erinnerung; nach weiteren 3 Tagen Aufgabe zur manuellen Entscheidung. Keine automatische Archivierung. Teilantworten und Versandfehler müssen fachlich geklärt werden. Diese Demo startet keine Uhr und simuliert keine Zustellung.','Only following an actual request: reminder after 3 calendar days without response; after another 3 days a task for human decision. No automatic archiving. Partial replies and delivery errors require clarification. This demo starts no clock and simulates no delivery.')}</p></details></div></div>`}<h3>${t('Lokaler Verlauf','Local history')}</h3>${reviewLog()}<p>${t('Dokumentprüfung ist keine Zulassung. Vertrag, Zahlung und technischer Zugang bleiben getrennt.','Document review is not admission. Contract, payment and technical access remain separate.')}</p><p><a href="#/workflow/WF-W03-03-01">WF-W03-03-01</a> · <a href="#/workflow/WF-W03-03-02">WF-W03-03-02</a> · W2G §3.3, §0.4/0.8/0.9, §3.8</p></section>`}
function reviewAction(act){const a=ADMISSIONS;a.error='';if(act==='start'&&!a.started){a.started=true;a.events.push(['Entwurf lokal übernommen · Erstkontakt-Aufgabe offen.','Draft opened locally · first-contact task pending.'])}else if(act==='review'&&a.started){if(reviewPending()){a.error=t('Vorhandene Muster zuerst prüfen; unklare Dokumente ausdrücklich als ungeklärt markieren.','Review existing samples first; explicitly mark uncertain documents as unclear.');render();document.getElementById('review-error')?.focus();return}a.reviewed=true;a.events.push(['Vollständigkeitsprüfung lokal vorgemerkt · keine Fachentscheidung.','Completeness review recorded locally · no eligibility decision.']);if(!reviewIssues().length)a.request=null;else if(a.request){a.request.items=reviewIssues();a.request.labels=Object.fromEntries(reviewIssues().map(i=>[i,state.uploads[i]?reviewLabels[a.quality[i]||'pending']:['Muster fehlt','Sample missing']]))}}else if(act==='request'&&a.started&&a.reviewed&&reviewIssues().length){if(!a.reason.trim()){a.error=t('Bitte eine fiktive Begründung ergänzen.','Please add a fictional reason.');render();document.getElementById('review-reason')?.focus();return}a.request={items:reviewIssues(),labels:Object.fromEntries(reviewIssues().map(i=>[i,state.uploads[i]?reviewLabels[a.quality[i]||'pending']:['Muster fehlt','Sample missing']])),reason:a.reason.trim(),responded:false};a.events.push(['Nachforderung lokal vorbereitet · nicht versendet.','Document request prepared locally · not sent.'])}else if(act.startsWith('document-')&&a.request){const i=Number(act.split('-')[1]);if(![0,1,2].includes(i))return;state.uploads[i]=true;a.quality[i]='pending';a.reviewed=false;a.events.push(['Musterunterlage '+(i+1)+' ergänzt, erneute Prüfung offen.','Sample document '+(i+1)+' added; review pending.'])}else if(act==='respond'&&a.request&&!a.request.responded){a.request.responded=true;a.reviewed=false;a.events.push(['Nachreichung lokal vorgemerkt · erneute Prüfung erforderlich.','Additional evidence noted locally · review required.'])}render();document.getElementById(route().startsWith('/staff/')?'review-title':'review-status')?.focus()}
const admissionsBody=v3Body;v3Body=function(r){if(r==='/staff/admissions'||r.startsWith('/staff/admissions/'))return reviewStaff(r);return admissionsBody(r)};
const admissionsPortal=portalContent;portalContent=function(role,view){return (role==='applicant'&&view==='overview'&&ADMISSIONS.started?`<h1>${t('Deine Bewerberakte','Your applicant record')}</h1><p>${esc(state.application.course)} · ${esc(applicationChoiceLabel(state.application.language))}</p>${applicationDraftDetails()}${link(t('Entwurf bearbeiten','Edit draft'),'/apply','secondary')}`:admissionsPortal(role,view))+(role==='applicant'&&['overview','tasks','messages','documents'].includes(view)?reviewApplicant():'')};
const admissionsBind=v3Bind;v3Bind=function(){admissionsBind();document.querySelectorAll('[data-review-action]').forEach(el=>el.addEventListener('click',()=>reviewAction(el.dataset.reviewAction)));document.querySelectorAll('[data-review-quality]').forEach(el=>el.addEventListener('change',()=>{ADMISSIONS.quality[el.dataset.reviewQuality]=el.value;ADMISSIONS.reviewed=false;render();document.querySelector('[data-review-quality="'+el.dataset.reviewQuality+'"]')?.focus()}));document.getElementById('review-reason')?.addEventListener('input',e=>{ADMISSIONS.reason=e.target.value})};
const admissionsAction=action;action=function(a,v){if(a==='upload'&&ADMISSIONS.started){ADMISSIONS.quality[Number(v||0)]='pending';ADMISSIONS.reviewed=false}return admissionsAction(a,v)};
render();
